def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def get_pos(key, default=None):
        p = observation.get(key, default)
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            return p[0], p[1]
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, tgt):
        return [clamp_step(tgt[0] - src[0]), clamp_step(tgt[1] - src[1])]

    def step_away(src, tgt):
        return [clamp_step(src[0] - tgt[0]), clamp_step(src[1] - tgt[1])]

    def best_by_dist(items, src):
        best = None
        best_d = None
        for it in items:
            if isinstance(it, (list, tuple)) and len(it) >= 2:
                d = dist(src, (it[0], it[1]))
                if best is None or d < best_d:
                    best = (it[0], it[1])
                    best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    self_pos = get_pos("self_position", (0, 0))
    opp_pos = get_pos("opponent_position", self_pos)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            move = step_toward(self_pos, opp_pos)
            if move == [0, 0]:
                return [0, 0]
            return move
        w = observation.get("grid_width", 0)
        h = observation.get("grid_height", 0)
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = None
        best_d = None
        for c in corners:
            d = dist(opp_pos, c)
            if target is None or d > best_d:
                target = c
                best_d = d
        move = step_toward(self_pos, target)
        if move != [0, 0]:
            return move
        return step_away(self_pos, opp_pos)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        target = best_by_dist(targets, self_pos)
        if target is not None:
            return step_toward(self_pos, target)
        opp_terr = observation.get("opponent_territory") or []
        target = best_by_dist(opp_terr, self_pos)
        if target is not None:
            return step_toward(self_pos, target)
        return step_toward(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = best_by_dist(resources, self_pos)
    if target is not None:
        return step_toward(self_pos, target)

    threats = observation.get("threats") or observation.get("opponents") or []
    threat = best_by_dist(threats, self_pos)
    if threat is not None and dist(self_pos, threat) <= 2:
        return step_away(self_pos, threat)

    if env == "resource_collection":
        return step_toward(self_pos, opp_pos)

    return [0, 0]

